// ---------------------------------------------------------------------------
// Valve factory entry (dlsym'ed by name "CreateInterface"; kept via
// -Wl,--export-dynamic-symbol=CreateInterface in link.sh).  Answers the
// three vphysics interface names the engine / game DLLs request:
//   - launcher AppSystemGroup table:  { "vphysics", VPhysics031 }
//   - sys_dll2.cpp CEngineAPI/CStdFileSystem Connect: g_pPhysics = VPhysics031
//   - cmodel_bsp.cpp CollisionBSPData_LinkPhysics:
//       VPhysicsSurfaceProps001 + VPhysicsCollision007
//   - game/server/physics.cpp CPhysicsHook::Init: all three
// ---------------------------------------------------------------------------
extern "C" __attribute__((visibility("default")))
void *CreateInterface( const char *pName, int *pReturnCode )
{
        static bool s_bInit = false;
        if ( !s_bInit )
        {
                s_bInit = true;
                csarm_InitVPhysicsStubs();
        }
        if ( pName )
        {
                void *p = g_PhysIface ? s_PhysicsStub.QueryInterface( pName ) : NULL;
                if ( p )
                {
                        if ( pReturnCode )
                                *pReturnCode = IFACE_OK;
                        return p;
                }
        }
        if ( pReturnCode )
                *pReturnCode = IFACE_FAILED;
        return NULL;
}
